{
  // Foreach node: {{ name }}
  // This node contains inner nodes that will be executed for each item in the loop
  // Inner nodes:
  // - {{ name }}_start: Traverse start controller
  // - {{ name }}_sql: SQL node that runs for each iteration
  // - {{ name }}_shell: Shell node that runs for each iteration
  // - {{ name }}_end: Traverse end controller
}

{{ name }}_start/{{ name }}_start.sh.content:
#!/bin/bash
# Traverse start controller for {{ name }}
# This script marks the beginning of each iteration

echo "[{{ name }}_start] Starting iteration: ${loop_index}"
echo "[{{ name }}_start] Current item: ${item}"

{{ name }}_start/{{ name }}_start.schedu.content:
{
  // Inner node: {{ name }}_start
  // Type: VIRTUAL (CONTROLLER_TRAVERSE_START)
  // Parent: {{ name }} (FOREACH)
  "id": "{{ name }}_start",
  "name": "{{ name }}_start",
  "type": "VIRTUAL",
  "script": {
    "path": "{{ name }}_start/{{ name }}_start.sh",
    "runtime": {
      "command": "CONTROLLER_TRAVERSE_START"
    }
  }
}

